orders_fulfilled_at_after_accepted_at_ch.value:
"app"."orders"."fulfilled_at" is null or (
        "app"."orders"."accepted_at" is not null and "app"."orders"."fulfilled_at" >= "app"."orders"."accepted_at"
      )

promotion_redemption_claims_reserved_tim.value:
"app"."promotion_redemption_claims"."status" <> 'RESERVED' or (
        "app"."promotion_redemption_claims"."consumed_at" is null and "app"."promotion_redemption_claims"."released_at" is null
      )

promotion_redemption_claims_consumed_tim.value:
"app"."promotion_redemption_claims"."status" <> 'CONSUMED' or (
        "app"."promotion_redemption_claims"."consumed_at" is not null and "app"."promotion_redemption_claims"."released_at" is null
      )

promotion_redemption_claims_released_tim.value:
"app"."promotion_redemption_claims"."status" <> 'RELEASED' or (
        "app"."promotion_redemption_claims"."consumed_at" is null and "app"."promotion_redemption_claims"."released_at" is not null
      )
